ST.xhtml:
(* ---- program identity (scenario = motion3axis) ---- *)
prog_id := 1;

(* ---- stop: all axis drives off, in-position dropped ---- *)
IF stop_btn THEN
    running := FALSE;
END_IF;

IF NOT running THEN
    x_fwd := FALSE; x_rev := FALSE;
    y_fwd := FALSE; y_rev := FALSE;
    z_fwd := FALSE; z_rev := FALSE;
    in_pos := FALSE;
    IF start_btn THEN
        running := TRUE;
    END_IF;
ELSE
    (* ---- Z safe-zone interlock: X/Y axes may move only while Z is in the upper safe zone ---- *)
    xy_enable := z_fb <= 30;

    (* ---- X axis: dead-band positioning (±2) ---- *)
    IF x_sp - x_fb > 2 THEN
        x_fwd := TRUE;  x_rev := FALSE;
    ELSIF x_sp - x_fb < -2 THEN
        x_fwd := FALSE; x_rev := TRUE;
    ELSE
        x_fwd := FALSE; x_rev := FALSE;
    END_IF;
    IF NOT xy_enable THEN
        x_fwd := FALSE; x_rev := FALSE;
    END_IF;

    (* ---- Y axis: dead-band positioning (±2) ---- *)
    IF y_sp - y_fb > 2 THEN
        y_fwd := TRUE;  y_rev := FALSE;
    ELSIF y_sp - y_fb < -2 THEN
        y_fwd := FALSE; y_rev := TRUE;
    ELSE
        y_fwd := FALSE; y_rev := FALSE;
    END_IF;
    IF NOT xy_enable THEN
        y_fwd := FALSE; y_rev := FALSE;
    END_IF;

    (* ---- Z axis: dead-band positioning (±2), no interlock ---- *)
    IF z_sp - z_fb > 2 THEN
        z_fwd := TRUE;  z_rev := FALSE;
    ELSIF z_sp - z_fb < -2 THEN
        z_fwd := FALSE; z_rev := TRUE;
    ELSE
        z_fwd := FALSE; z_rev := FALSE;
    END_IF;
END_IF;

(* ---- in-position aggregate: all three axes inside dead band while running ---- *)
x_ok := ABS(x_sp - x_fb) <= 2;
y_ok := ABS(y_sp - y_fb) <= 2;
z_ok := ABS(z_sp - z_fb) <= 2;
in_pos := running AND x_ok AND y_ok AND z_ok;
moving := running AND (x_fwd OR x_rev OR y_fwd OR y_rev OR z_fwd OR z_rev);
